// ========== WEBHOOK ==========
add_action('wpforms_process_complete', 'mifeco_pipeline_webhook', 10, 4);
function mifeco_pipeline_webhook($fields, $entry, $form_data, $entry_id) {
    $form_name = $form_data['settings']['form_title'] ?? '';
    $pipeline = 'unknown';
    if (stripos($form_name, 'Consulting') !== false) $pipeline = 'consulting';
    elseif (stripos($form_name, 'Book') !== false) $pipeline = 'books';
    elseif (stripos($form_name, 'SaaS') !== false) $pipeline = 'saas';

    $data = ['pipeline' => $pipeline, 'form_name' => $form_name, 'entry_id' => $entry_id, 'timestamp' => current_time('mysql'), 'fields' => []];
    foreach ($fields as $f) $data['fields'][] = ['name' => $f['name'] ?? '', 'value' => $f['value'] ?? ''];

    $r = wp_remote_post('http://localhost:8080/api/webhook/wpforms', [
        'headers' => ['Content-Type' => 'application/json'],
        'body' => json_encode($data),
        'timeout' => 15,
    ]);
    if (is_wp_error($r)) error_log('MIFECO Webhook Error: ' . $r->get_error_message());
}


// ========== MIFECO EMAIL SENDER ==========
// Subject line identifier rule: ALL emails must contain [SaaS], [Books], or [Consulting]

add_action('rest_api_init', function() {
    register_rest_route('mifeco/v1', '/send-email', [
        'methods' => 'POST',
        'callback' => 'mifeco_handle_send_email',
        'permission_callback' => function($request) {
            return $request->get_param('secret') === 'Rm2214ri%%%%';
        },
    ]);
});

function mifeco_handle_send_email($request) {
    $email_data = $request->get_param('email');
    if (!$email_data || !isset($email_data['subject']) || !isset($email_data['body'])) {
        return new WP_REST_Response(['success' => false, 'error' => 'Missing required fields: subject, body'], 400);
    }

    $subject = sanitize_text_field($email_data['subject']);
    $body = wp_kses_post($email_data['body']);
    $to = isset($email_data['to']) ? sanitize_email($email_data['to']) : 'info@mifeco.com';
    $pipeline = isset($email_data['pipeline']) ? sanitize_text_field($email_data['pipeline']) : '';

    $identifiers = array('SaaS', 'Books', 'Consulting');
    $found_identifier = '';
    foreach ($identifiers as $id) {
        if (stripos($subject, "[$id]") !== false) {
            $found_identifier = $id;
            break;
        }
    }
    if (!$found_identifier && $pipeline && in_array(ucfirst(strtolower($pipeline)), $identifiers)) {
        $found_identifier = ucfirst(strtolower($pipeline));
        $subject = '[' . $found_identifier . '] ' . $subject;
    }

    $headers = array(
        'From: MIFECO <info@mifeco.com>',
        'Reply-To: info@mifeco.com',
        'Content-Type: text/html; charset=UTF-8',
        'X-MIFECO-Pipeline: ' . $found_identifier,
    );

    $sent = wp_mail($to, $subject, nl2br($body), $headers);
    return new WP_REST_Response(array(
        'success' => $sent,
        'to' => $to,
        'subject' => $subject,
        'pipeline' => $found_identifier,
        'message' => $sent ? 'Email sent successfully' : 'Failed to send email',
    ), $sent ? 200 : 500);
}

